package com.jobpilot.integration;import com.jobpilot.user.User;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.stereotype.Service;@Service public class MailAlertService{private final JavaMailSender mail;private final String username;public MailAlertService(JavaMailSender m,@Value("${spring.mail.username:}")String u){mail=m;username=u;}public void newJobs(User user,int count){if(username.isBlank()||!user.isAlertsEnabled())return;var msg=new SimpleMailMessage();msg.setFrom(username);msg.setTo(user.getEmail());msg.setSubject("DanJobs encontró "+count+" vacantes");msg.setText("Tienes "+count+" nuevas vacantes compatibles. Ingresa a DanJobs para revisarlas.");mail.send(msg);}}
